public final class DirectorPlan {public static final int MAX_STEPS=32,MAX_REQUIREMENTS=64;private final String planId,sourceDecisionId,goal,contextFingerprint;private final com.sobrenaturaldirector.decision.model.Intent intent;private final PlanHorizon horizon;private final PlanStatus status;private final List<PlanStep> steps;private final List<PlanRequirement> requirements;private final Map<String,Double> budgetEstimate;private final String fallbackStrategy,replanPolicy;public DirectorPlan(String id,String source,com.sobrenaturaldirector.decision.model.Intent intent,String goal,PlanHorizon horizon,PlanStatus status,List<PlanStep>steps,List<PlanRequirement>requirements,Map<String,Double>budget,String fingerprint,String fallback,String replan){if(id==null||id.length()==0||source==null||intent==null||goal==null||horizon==null||status==null||steps==null||requirements==null||steps.size()>MAX_STEPS||requirements.size()>MAX_REQUIREMENTS)throw new IllegalArgumentException("invalid plan");planId=id;sourceDecisionId=source;this.intent=intent;this.goal=goal;this.horizon=horizon;this.status=status;this.steps=Collections.unmodifiableList(new ArrayList<PlanStep>(steps));this.requirements=Collections.unmodifiableList(new ArrayList<PlanRequirement>(requirements));budgetEstimate=Collections.unmodifiableMap(new TreeMap<String,Double>(budget==null?Collections.<String,Double>emptyMap():budget));contextFingerprint=fingerprint==null?"":fingerprint;fallbackStrategy=fallback==null?"DEFER":fallback;replanPolicy=replan==null?"BOUNDED":replan;}public String getPlanId(){return planId;}public String getSourceDecisionId(){return sourceDecisionId;}public com.sobrenaturaldirector.decision.model.Intent getIntent(){return intent;}public String getGoal(){return goal;}public PlanHorizon getHorizon(){return horizon;}public PlanStatus getStatus(){return status;}public List<PlanStep>getSteps(){return steps;}public List<PlanRequirement>getRequirements(){return requirements;}public Map<String,Double>getBudgetEstimate(){return budgetEstimate;}public String getContextFingerprint(){return contextFingerprint;}public String getFallbackStrategy(){return fallbackStrategy;}public String getReplanPolicy(){return replanPolicy;} }
